    fn first_enabled_transition(
        &mut self,
        state: Self::State,
        event: Self::Event,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) -> Option<::sce_rust_runtime::TransitionId> {
        match state {
            InternalChainIsBoundedState::Alt => {
                if event == InternalChainIsBoundedEvent::Tick {
                    {
                        // alt, transition 0
                        return Some(::sce_rust_runtime::TransitionId(14));
                    }
                }
                if event == InternalChainIsBoundedEvent::Null {
                    if self.safe_evaluate_guard("_scxml_eq(pending, 1)", engine) {
                        // alt, transition 1
                        return Some(::sce_rust_runtime::TransitionId(15));
                    }
                }
                if event == InternalChainIsBoundedEvent::Poke {
                    {
                        // alt, transition 2
                        return Some(::sce_rust_runtime::TransitionId(16));
                    }
                }
                None
            }
            InternalChainIsBoundedState::Bounded => {
                if event == InternalChainIsBoundedEvent::Link {
                    if self.safe_evaluate_guard("(laps < 999)", engine) {
                        // bounded, transition 0
                        return Some(::sce_rust_runtime::TransitionId(6));
                    }
                }
                if event == InternalChainIsBoundedEvent::Link {
                    {
                        // bounded, transition 1
                        return Some(::sce_rust_runtime::TransitionId(7));
                    }
                }
                if event == InternalChainIsBoundedEvent::Poke {
                    {
                        // bounded, transition 2
                        return Some(::sce_rust_runtime::TransitionId(8));
                    }
                }
                None
            }
            InternalChainIsBoundedState::Idle => {
                if event == InternalChainIsBoundedEvent::Poke {
                    {
                        // idle, transition 0
                        return Some(::sce_rust_runtime::TransitionId(0));
                    }
                }
                if event == InternalChainIsBoundedEvent::Bounded {
                    {
                        // idle, transition 1
                        return Some(::sce_rust_runtime::TransitionId(1));
                    }
                }
                if event == InternalChainIsBoundedEvent::Spin {
                    {
                        // idle, transition 2
                        return Some(::sce_rust_runtime::TransitionId(2));
                    }
                }
                if event == InternalChainIsBoundedEvent::Resume {
                    {
                        // idle, transition 3
                        return Some(::sce_rust_runtime::TransitionId(3));
                    }
                }
                if event == InternalChainIsBoundedEvent::Alternate {
                    {
                        // idle, transition 4
                        return Some(::sce_rust_runtime::TransitionId(4));
                    }
                }
                if event == InternalChainIsBoundedEvent::Unanswered {
                    {
                        // idle, transition 5
                        return Some(::sce_rust_runtime::TransitionId(5));
                    }
                }
                None
            }
            InternalChainIsBoundedState::Ignoring => {
                if event == InternalChainIsBoundedEvent::Beatless {
                    if self.safe_evaluate_guard("(ignores < 999)", engine) {
                        // ignoring, transition 0
                        return Some(::sce_rust_runtime::TransitionId(17));
                    }
                }
                if event == InternalChainIsBoundedEvent::Beatless {
                    {
                        // ignoring, transition 1
                        return Some(::sce_rust_runtime::TransitionId(18));
                    }
                }
                if event == InternalChainIsBoundedEvent::Poke {
                    {
                        // ignoring, transition 2
                        return Some(::sce_rust_runtime::TransitionId(19));
                    }
                }
                None
            }
            InternalChainIsBoundedState::Resuming => {
                if event == InternalChainIsBoundedEvent::Beat {
                    if self.safe_evaluate_guard("(beats < 1499)", engine) {
                        // resuming, transition 0
                        return Some(::sce_rust_runtime::TransitionId(11));
                    }
                }
                if event == InternalChainIsBoundedEvent::Beat {
                    {
                        // resuming, transition 1
                        return Some(::sce_rust_runtime::TransitionId(12));
                    }
                }
                if event == InternalChainIsBoundedEvent::Poke {
                    {
                        // resuming, transition 2
                        return Some(::sce_rust_runtime::TransitionId(13));
                    }
                }
                None
            }
            InternalChainIsBoundedState::Spin => {
                if event == InternalChainIsBoundedEvent::Link {
                    {
                        // spin, transition 0
                        return Some(::sce_rust_runtime::TransitionId(9));
                    }
                }
                if event == InternalChainIsBoundedEvent::Poke {
                    {
                        // spin, transition 1
                        return Some(::sce_rust_runtime::TransitionId(10));
                    }
                }
                None
            }
            _ => None,
        }
    }

